public static int constructTargetString(String T, List<List<String>> bags) {
    int len = T.length();
    int n = bags.size();
    int[][] dp = new int[n + 1][len + 1];

    for (int i = 0; i <= n; i++) {
        Arrays.fill(dp[i], Integer.MAX_VALUE);
    }

    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        List<String> bag = bags.get(i - 1);
        for (String th : bag) {
            for (int j = 0; j <= len; j++) {
                if (dp[i - 1][j] == Integer.MAX_VALUE) continue;
                dp[i][j] = Math.min(dp[i - 1][j], dp[i][j]);
                if (j + th.length() <= len && T.startsWith(th, j)) {
                    dp[i][j + th.length()] = Math.min(dp[i - 1][j] + 1, dp[i][j + th.length()]);
                }
            }
        }
    }

    return dp[n][len] == Integer.MAX_VALUE ? -1 : dp[n][len];
}
